INSERT INTO `chapter_periskop` (`book_id`, `chapter`, `verses`, `title`) VALUES
(23, 60, 1, 'I. Panurirangon taringot tu hatiuron na binsar di Sion dohot taringot tu hamubaon ni roha ni angka parbegu tu Jahowa'),
