(53, 1, 1, 'I. Dipuji apostel i haporseaonnasida. Baloshonon ni Debata do tu ganup, hombar tu parrohaonna 1-12'),
(53, 2, 1, 'I. Haroro ni Kristus dohot patujolona 1-17'),
(53, 3, 1, 'I. Angka sipaingot: unang tadingkon hamu ruhut na denggan! 1-18'),
(54, 1, 1, 'I. Tabi ni apostel i'),
(54, 1, 3, 'II. Hata na mamolin i do sitiopon'),
(54, 1, 12, 'III. Pangasii ni Debata di apostel i'),
(54, 2, 1, 'I. Tangiang humongkop saluhut jolma'),
(54, 3, 1, 'I. Taringot tu tohonan sintua dohot parhobas'),
(54, 4, 1, 'I. Angka parpoda haliluon'),
(54, 5, 1, 'I. Siingoton ni si Timoteus maradophon na tuatua dohot na mabalu'),
(54, 6, 1, 'I. Sipaingot tu angka anak somang'),
(54, 6, 6, 'II. Uli ni roha na sabam'),
(55, 1, 1, 'I. Tabi ni apostel i'),
(55, 1, 3, 'II. Las ni rohana dohot holongna mida si Timoteus');
INSERT INTO `chapter_periskop` (`book_id`, `chapter`, `verses`, `title`) VALUES
(55, 1, 6, 'III. Ndang sihailahononhon barita na uli i'),
(55, 2, 1, 'I. Taon ma na porsuk i humongkop Kristus!'),
(55, 3, 1, 'I. Parhehe ni angka parjahat di tingki parpudi'),
(55, 4, 1, 'I. Burju ma radoti tohonanmi!'),
(55, 4, 6, 'II. Jonok nama ajal ni apostel i'),
(56, 1, 1, 'I. Hata pamungkaan'),
(56, 1, 5, 'II. Taringot tu hasintuaon'),
(56, 2, 1, 'I. Angka aturan di huria'),
(56, 3, 1, 'I. Parange na ture mangula tohonan parhuriaon'),
(56, 3, 3, 'II. Haluaon na pinature ni Debata di hita'),
(57, 1, 1, 'I. Tabi ni apostel i'),
(57, 1, 4, 'II. Las ni rohana mida haporseaon ni si Pilemon'),
(57, 1, 8, 'III. Pangondihonna di si Onesimus'),
(58, 1, 1, 'I. Marhite sian Anak i do dipapatar Debata dirina'),
(58, 2, 1, 'I. Sioloan do hata ni Nasumurung i'),
(58, 2, 5, 'II. Tumoru Anak i satongkin sian angka surusuruan i'),
(58, 3, 1, 'I. Sumurung do Kristus sian si Musa'),
(58, 4, 1, 'I. Taharinggashon ma masuk tu paradianan i!'),
(58, 4, 11, 'II. Gogo dohot tajom ni hata ni Debata'),
(58, 5, 1, 'I. Sintua ni malim na tutu do Kristus'),
(58, 6, 1, 'I. Jea ni na marbalik sian haporseaon'),
(58, 7, 1, 'I. Sangap ni si Melkisedek, na targoar tudutudu tu Kristus'),
(58, 9, 1, 'I. Tudutudu tu padan na imbaru do joro najolo i'),
(58, 10, 1, 'I. Surung dohot gogo ni panghongkop ni Tuhan Jesus'),
(58, 11, 1, 'I. Pangalaho ni haporseaon, tarida sian angka parhaporseaon, uju di padan na robi 1-40'),
(58, 12, 1, 'I. Mamereng dompak Tuhan Jesus jala marbenget ni roha di pangunjunan'),
(58, 13, 1, 'I. Angka sipaingot'),
(59, 1, 1, 'I. Tabi ni apostel i'),
(59, 1, 2, 'II. Pasupasu na sian pangunjunan'),
(59, 1, 13, 'III. Holan na denggan do ro sian Debata'),
(59, 2, 1, 'I. Unang ma masa di huria parnidaon di bohi'),
(59, 2, 8, 'II. Ruhut masihaholongan, i do patik raja'),
(59, 3, 1, 'I. Jorbut ni dosa ni dila'),
(59, 4, 1, 'I. Jea ni roha portibi on; martua do na saor tu Debata'),
(59, 5, 1, 'I. Jea ni na mora'),
(59, 5, 7, 'II. Songkal dohot uli ni ari parpudi'),
(60, 1, 1, 'I. Tabi ni apostel i'),
(60, 1, 3, 'II. Taringot tu pangkirimon na mangolu'),
(60, 2, 1, 'I. Gabe batu na mangolu ma hamu di joro ni Debata!'),
(60, 2, 11, 'II. Oromon do hisap ni roha; ulahononhon do pangoloion'),
(60, 3, 1, 'I. Sipaingot tu na mardongan saripe'),
(60, 3, 8, 'II. Lambok ni roha do siparangehononhon'),
(60, 4, 1, 'I. Parange ni sisean ni Kristus'),
(60, 5, 1, 'I. Taringot tu ulaon ni angka sintua'),
(60, 5, 5, 'II. Sipaingot paserephon jala patoguhon roha'),
(61, 1, 1, 'I. Tabi ni apostel i'),
(61, 1, 3, 'II. Sipaingot, mamarangehon habadiaon'),
(61, 1, 12, 'III. Hasangapon ni Tuhan Jesus, na niida ni apostel i'),
(61, 2, 1, 'I. Lumbalumba taringot tu parpoda haliluon 1-22'),
